SELECT CASE WHEN suppliers.rating >= 4.4 THEN 'high' WHEN suppliers.rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, suppliers.city, MAX(products.launch_date) AS last_launch_date FROM products LEFT JOIN suppliers ON suppliers.id = products.supplier_id GROUP BY CASE WHEN suppliers.rating >= 4.4 THEN 'high' WHEN suppliers.rating >= 1.9 THEN 'mid' ELSE 'low' END, suppliers.city;
